// The match in sentence case: the first word capitalized and the rest
// lowercased. A word with a capital past its first letter ("JavaScript",
// "API") is kept as written, and so is "I". The first word after a colon is
// capitalized too.
text := import("text")

words := text.split(match, " ")
out := []
first := true
for w in words {
    if w == "" {
        out = append(out, w)
        continue
    }
    if first {
        found := text.re_find(`^(\PL*)(\pL)(.*)$`, w)
        if found != undefined {
            w = found[0][1].text + text.to_upper(found[0][2].text) + found[0][3].text
        }
        first = false
    } else if !text.re_match(`^\PL*\pL.*\p{Lu}|^\PL*I(\PL.*)?$`, w) {
        w = text.to_lower(w)
    }
    if text.has_suffix(w, ":") {
        first = true
    }
    out = append(out, w)
}

suggestions := [text.join(out, " ")]

// The match in title case: every word capitalized except articles, short
// conjunctions, and short prepositions in the middle. A word with a capital
// past its first letter ("JavaScript", "API") is kept as written.
text := import("text")

small := {
    "a": true, "an": true, "and": true, "as": true, "at": true, "but": true, "by": true,
    "for": true, "if": true, "in": true, "nor": true, "of": true, "on": true, "or": true,
    "per": true, "so": true, "the": true, "to": true, "up": true, "via": true, "vs": true,
    "yet": true, "from": true, "into": true, "onto": true, "with": true
}

// The first letter of a word, after any leading punctuation, in upper case.
upper := func(w) {
    found := text.re_find(`^(\PL*)(\pL)(.*)$`, w)
    if found == undefined {
        return w
    }
    return found[0][1].text + text.to_upper(found[0][2].text) + found[0][3].text
}

words := text.split(match, " ")
last := len(words) - 1
for last > 0 && words[last] == "" {
    last--
}

out := []
for i, w in words {
    if w == "" || text.re_match(`^\PL*\pL.*\p{Lu}`, w) {
        out = append(out, w)
        continue
    }
    bare := text.to_lower(text.re_replace(`^\PL+|\PL+$`, w, ""))
    if i > 0 && i < last && small[bare] && !text.has_suffix(out[i - 1], ":") {
        out = append(out, text.to_lower(w))
        continue
    }
    // Each part of a hyphenated word: "Built-In".
    parts := []
    for p in text.split(w, "-") {
        parts = append(parts, upper(p))
    }
    out = append(out, text.join(parts, "-"))
}

suggestions := [text.join(out, " ")]

// Numbered headings ("1.", "1.2") that skip or repeat a number. Use with
// `scope: raw` on Markdown, since the check needs every heading at once.
text := import("text")

matches := []

prev := []     // the last number seen, as a list of ints
fenced := ""   // the open code fence, if any
offset := 0

for line in text.split(scope, "\n") {
    start := offset
    offset += len(line) + 1

    fence := text.re_find(`^ {0,3}(` + "```" + `|~~~)`, line)
    if fenced != "" {
        if fence != undefined && fence[0][1].text == fenced {
            fenced = ""
        }
        continue
    } else if fence != undefined {
        fenced = fence[0][1].text
        continue
    }

    found := text.re_find(`^ {0,3}#{1,6}[ \t]+(\d+(?:\.\d+)*)(\.?)(?:[ \t]|$)`, line)
    if found == undefined {
        continue
    }

    // "1." or "1.2", but not a bare "2024".
    written := found[0][1]
    if !text.contains(written.text, ".") && found[0][2].text == "" {
        continue
    }

    parts := []
    for p in text.split(written.text, ".") {
        parts = append(parts, int(p))
    }

    want := []
    k := len(parts)
    if k <= len(prev) {
        for i := 0; i < k - 1; i++ {
            want = append(want, prev[i])
        }
        want = append(want, prev[k - 1] + 1)
    } else {
        // One level down; deeper than that skips a level.
        want = append(copy(prev), 1)
    }

    // A document may count from zero.
    if len(prev) == 0 && k == 1 && parts[0] == 0 {
        want = [0]
    }

    labels := []
    for n in want {
        labels = append(labels, string(n))
    }
    expected := text.join(labels, ".")
    if written.text != expected {
        matches = append(matches, {
            begin: start + written.begin,
            end: start + written.end,
            message: "Heading number '%s' is out of sequence; expected '" + expected + "'."
        })
    }
    prev = parts
}

// A list whose items mix ending punctuation: some end with a period and some
// don't. Use with `scope: raw` on Markdown. The items in the minority are
// flagged; an item ending with a colon introduces what follows and is skipped.
text := import("text")

matches := []

open := []     // the lists being read, innermost last
fenced := ""   // the open code fence, if any
offset := 0

// Flag the items that disagree with the rest of their list.
check := func(items) {
    ended := []
    bare := []
    for item in items {
        if text.has_suffix(item.text, ":") {
            continue
        } else if text.re_match(`[.!?]["')\]*_]*$`, item.text) {
            ended = append(ended, item)
        } else {
            bare = append(bare, item)
        }
    }
    if len(ended) == 0 || len(bare) == 0 {
        return
    }
    flag := bare
    if len(bare) > len(ended) {
        flag = ended
    }
    for item in flag {
        matches = append(matches, {begin: item.begin, end: item.end})
    }
}

closeTo := func(indent) {
    for len(open) > 0 && open[len(open) - 1].indent > indent {
        check(open[len(open) - 1].items)
        open = open[:len(open) - 1]
    }
}

for line in text.split(scope, "\n") {
    start := offset
    offset += len(line) + 1
    line = text.trim_right(line, "\r")

    fence := text.re_find(`^([ \t]*)(` + "```" + `|~~~)`, line)
    if fenced != "" {
        if fence != undefined && fence[0][2].text == fenced {
            fenced = ""
        }
        continue
    } else if fence != undefined {
        fenced = fence[0][2].text
        if fence[0][1].text == "" {
            closeTo(-1)
        }
        continue
    }

    if text.trim_space(line) == "" {
        continue
    }

    // A thematic break, "* * *", is not an item.
    if text.re_match(`^ {0,3}([-*_])([ \t]*([-*_])){2,}[ \t]*$`, line) {
        closeTo(-1)
        continue
    }

    item := text.re_find(`^([ \t]*)(?:[-*+]|\d{1,9}[.)])[ \t]+(.+?)[ \t]*$`, line)
    if item != undefined {
        indent := len(item[0][1].text)
        closeTo(indent)
        entry := {
            text: item[0][2].text,
            begin: start + item[0][2].begin,
            end: start + item[0][2].end
        }
        if len(open) > 0 && open[len(open) - 1].indent == indent {
            last := open[len(open) - 1]
            last.items = append(last.items, entry)
        } else {
            open = append(open, {indent: indent, items: [entry]})
        }
        continue
    }

    lead := len(text.re_find(`^[ \t]*`, line)[0][0].text)
    if len(open) == 0 || lead == 0 {
        // A paragraph, heading, or table ends every open list.
        closeTo(-1)
        continue
    }

    // A wrapped line: the item now ends where this line does.
    body := text.trim_space(line)
    last := open[len(open) - 1].items[len(open[len(open) - 1].items) - 1]
    last.text = body
    last.begin = start + lead
    last.end = start + len(text.trim_right(line, " \t"))
}
closeTo(-1)

{{- /* GitHub Actions annotations: one workflow command per alert, so each
       shows up on the changed line in the pull request. Suggestions become
       notices, which GitHub shows without failing the check. */ -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{- $level := "notice" -}}
{{- if eq .Severity "error" -}}{{- $level = "error" -}}
{{- else if eq .Severity "warning" -}}{{- $level = "warning" -}}
{{- end -}}
::{{ $level }} file={{ $path }},line={{ .Line }},col={{ index .Span 0 }},endColumn={{ index .Span 1 }},title={{ .Check }}::{{ .Message }}
{{ end -}}
{{- end -}}

{{- /* GitLab Code Quality: a JSON array of issues, one per alert. The
       fingerprint hashes the path, position, rule, and match, so an alert
       keeps it from run to run until its text moves, and two matches on one
       line stay two issues. */ -}}
[
{{- $first := true -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{- $severity := "info" -}}
{{- if eq .Severity "error" -}}{{- $severity = "major" -}}
{{- else if eq .Severity "warning" -}}{{- $severity = "minor" -}}
{{- end -}}
{{- if not $first }},{{ end }}
  {{ dict "description" .Message "check_name" .Check "fingerprint" (printf "%s:%d:%d:%s:%s" $path .Line (index .Span 0) .Check .Match | sha256sum) "severity" $severity "location" (dict "path" $path "lines" (dict "begin" .Line)) | toJson }}
{{- $first = false -}}
{{- end -}}
{{- end }}
]

{{- /* JSON Lines: one object per alert, for a tool or an agent that reads
       alerts one at a time. Every field is JSON-encoded, so a message with a
       quote in it stays valid. */ -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{ dict "path" $path "line" .Line "column" (index .Span 0) "end" (index .Span 1) "check" .Check "severity" .Severity "message" .Message "match" .Match "link" .Link | toJson }}
{{ end -}}
{{- end -}}

{{- /* JUnit XML: a test suite per file and a test case per alert. Errors and
       warnings are failures; suggestions pass, so they are listed but never
       fail the build. */ -}}
{{- $tests := 0 -}}{{- $failures := 0 -}}
{{- range .Files -}}
{{- range .Alerts -}}
{{- $tests = add1 $tests -}}
{{- if ne .Severity "suggestion" -}}{{- $failures = add1 $failures -}}{{- end -}}
{{- end -}}
{{- end -}}
<?xml version="1.0" encoding="UTF-8"?>
<testsuites name="Vale" tests="{{ $tests }}" failures="{{ $failures }}">
{{- range .Files -}}
{{- $path := .Path -}}
{{- $n := 0 -}}
{{- range .Alerts -}}{{- if ne .Severity "suggestion" -}}{{- $n = add1 $n -}}{{- end -}}{{- end }}
  <testsuite name="{{ $path | html }}" tests="{{ len .Alerts }}" failures="{{ $n }}">
{{- range .Alerts }}
    <testcase name="{{ .Check | html }}" classname="{{ $path | html }}:{{ .Line }}:{{ index .Span 0 }}">
{{- if ne .Severity "suggestion" }}
      <failure type="{{ .Severity }}" message="{{ .Message | html }}">{{ $path | html }}:{{ .Line }}:{{ index .Span 0 }}: {{ .Message | html }}</failure>
    </testcase>
{{- else }}</testcase>
{{- end -}}
{{- end }}
  </testsuite>
{{- end }}
</testsuites>

{{- /* reviewdog rdjsonl: one diagnostic per line, for `reviewdog -f=rdjsonl`.
       The end column is one past the span, since reviewdog's range is
       exclusive. reviewdog counts columns in bytes and Vale in characters, so
       they differ after a line's first multi-byte character. */ -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{- $severity := "INFO" -}}
{{- if eq .Severity "error" -}}{{- $severity = "ERROR" -}}
{{- else if eq .Severity "warning" -}}{{- $severity = "WARNING" -}}
{{- end -}}
{"message": "{{ .Message | jsonEscape }}", "location": {"path": "{{ $path | jsonEscape }}", "range": {"start": {"line": {{ .Line }}, "column": {{ index .Span 0 }}}, "end": {"line": {{ .Line }}, "column": {{ add (index .Span 1) 1 }}}}}, "severity": "{{ $severity }}", "source": {"name": "vale"}, "code": {"value": "{{ .Check | jsonEscape }}"{{ if .Link }}, "url": "{{ .Link | jsonEscape }}"{{ end }}}}
{{ end -}}
{{- end -}}

{{- /* SARIF 2.1.0, for GitHub code scanning and other tools that keep a
       history of findings. Each rule that fired is described once. */ -}}
{{- $rules := dict -}}
{{- range .Files -}}
{{- range .Alerts -}}
{{- $_ := set $rules .Check (dict "link" .Link "text" .Description) -}}
{{- end -}}
{{- end -}}
{
  "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
  "version": "2.1.0",
  "runs": [
    {
      "tool": {
        "driver": {
          "name": "Vale",
          "informationUri": "https://vale.sh",
          "rules": [
{{- $first := true -}}
{{- range $id, $rule := $rules }}
{{ if not $first }},{{ end }}            {
              "id": "{{ $id | jsonEscape }}",
              "shortDescription": {"text": "{{ if $rule.text }}{{ $rule.text | jsonEscape }}{{ else }}{{ $id | jsonEscape }}{{ end }}"}
              {{- if $rule.link }},
              "helpUri": "{{ $rule.link | jsonEscape }}"
              {{- end }}
            }
{{- $first = false -}}
{{- end }}
          ]
        }
      },
      "results": [
{{- $first = true -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts }}
{{ if not $first }},{{ end }}        {
          "ruleId": "{{ .Check | jsonEscape }}",
          "level": "{{ if eq .Severity "error" }}error{{ else if eq .Severity "warning" }}warning{{ else }}note{{ end }}",
          "message": {"text": "{{ .Message | jsonEscape }}"},
          "locations": [
            {
              "physicalLocation": {
                "artifactLocation": {"uri": "{{ $path | jsonEscape }}"},
                "region": {
                  "startLine": {{ .Line }},
                  "startColumn": {{ index .Span 0 }},
                  "endColumn": {{ add (index .Span 1) 1 }},
                  "snippet": {"text": "{{ .Match | jsonEscape }}"}
                }
              }
            }
          ]
        }
{{- $first = false -}}
{{- end -}}
{{- end }}
      ]
    }
  ]
}

{{- /* A Markdown summary, for a pull request comment or a job summary:
       a table per file, then the totals. */ -}}
{{- $e := 0 -}}{{- $w := 0 -}}{{- $s := 0 -}}
{{- range .Files -}}
### `{{ .Path }}`

| Line | Level | Rule | Message |
| ---: | ----- | ---- | ------- |
{{ range .Alerts -}}
{{- if eq .Severity "error" -}}{{- $e = add1 $e -}}
{{- else if eq .Severity "warning" -}}{{- $w = add1 $w -}}
{{- else -}}{{- $s = add1 $s -}}{{- end -}}
| {{ .Line }}:{{ index .Span 0 }} | {{ .Severity }} | `{{ .Check }}` | {{ .Message }} |
{{ end }}
{{ end -}}
**{{ $e }} {{ $e | int | plural "error" "errors" }}, {{ $w }} {{ $w | int | plural "warning" "warnings" }}, {{ $s }} {{ $s | int | plural "suggestion" "suggestions" }}.**
